	if (nrow(raw_specs) == 0) {
		return(NULL)
	}

	column_or <- function(data, column, value = NA_real_) {
		if (column %in% names(data)) {
			data[[column]]
		} else {
			rep(value, nrow(data))
		}
	}

	rows <- list()
	for (i in seq_len(nrow(raw_specs))) {
		spec <- raw_specs[i, ]
		json_files <- list.files(spec$json_dir, pattern = "^typing-delay-benchmark-.*\\.json$", full.names = TRUE)
