		records <- as_tibble(raw$records) %>%
			filter(!isThrowaway)

		rows[[length(rows) + 1]] <- records %>%
			transmute(
				input_mode = spec$input_mode,
				delay_mode = spec$delay_mode,
				delay_ms = delayMs,
				round,
