			geom_errorbar(
				aes(ymin = keypress_p10_ms, ymax = keypress_p90_ms),
				width = 0.14,
				alpha = 0.45
			) +
			geom_text(
				aes(label_x, label_y, label = point_label),
				size = 3.0,
				check_overlap = FALSE,
				show.legend = FALSE
			) +
			scale_color_brewer(type = "qual", palette = "Dark2") +
			labs(
				title = "Trace-off evaluation paths only partially explain the gap",
