						cpu_qos_counter_join_contract <- tribble(
							~join_surface, ~required_fields, ~why_required, ~current_state, ~failure_mode_if_missing, ~add_before_root_run, ~mechanism_value_score, ~join_blocker_score, ~plot_label,
							"Retained key window identity",
							"run id; branch; delay; delay mode; sample index; retained/throwaway status; q50 inclusion; typed character",
							"Anchors every OS/browser counter sample to the same retained key that contributes to the benchmark q50.",
							"Partial: raw key timing exists in benchmark artifacts, but the compact CPU/QoS rows do not yet carry stable retained-key join ids.",
							"Root counters can only be compared as class medians, which is too weak for a mechanism claim.",
							TRUE, 5, 5, "retained key",
							"Input and EventDispatch timebase",
							"keydown/keypress/keyup enqueue times; EventDispatch start/end; browser monotonic clock; host wall-clock mapping",
							"Separates queueing or wakeup changes from listener-duration changes and makes sampled counters overlap the measured slice.",
							"Partial: Chromium traces have EventDispatch slices, but they are not currently joined to OS-counter sample ids.",
							"A fast row could be misread as faster JS work when only input enqueue or wakeup timing moved.",
							TRUE, 5, 5, "timebase",
							"Helper process lifetime and policy",
							"helper pid; process group; launch/start/end; command; nice/taskpolicy/QoS policy; CPU duration; exit status",
							"The decisive local split is policy-sensitive CPU: ordinary/utility rows are fast while background/maintenance rows stay slow.",
							"Partial: helper mode names are recorded, but per-retained-key PID, lifetime, and effective policy are not.",
							"The observed fast/slow split could be joined to the wrong helper or wrong policy window.",
							TRUE, 5, 4, "helper pid",
							"Renderer and browser process identity",
							"renderer pid; browser pid; main thread id if available; page target/frame id; browser revision",
							"Process-level counters need to identify the foreground renderer that handled the measured input.",
							"Partial: browser revision and trace target exist in some artifacts; renderer pid/thread id is not a stable sidecar field.",
							"Powermetrics or trace samples may describe the wrong process or aggregate away the foreground renderer.",
							TRUE, 5, 4, "renderer pid",
							"Collector sample join",
							"collector run id; powermetrics plist path; trace file path; sample begin/end; sample id; notification ids; sample interval",
							"Turns privileged sampled counters into per-key evidence instead of a run-level correlation.",
							"Missing: current artifacts do not record collector filenames, sample ids, or trace notifications.",
							"Counter rows cannot be audited against individual retained keys or source-span windows.",
							TRUE, 5, 5, "sample ids",
							"Observer overhead sentinels",
							"with/without collector control rows; collector pid; collector CPU; dropped samples; class-order preservation",
							"Root collectors and browser tracing can perturb exactly the scheduler and power state under test.",
							"Partial: existing no-trace/trace controls cover some browser-trace effects, but not root counter overhead.",
							"A counter-backed mechanism could be an artifact of the observer changing the class ordering.",
							TRUE, 4, 4, "overhead",
							"Environment and power metadata",
							"AC/battery state; low-power mode; thermal pressure; OS build; core counts; container state; browser build",
							"Power and scheduler hypotheses are host-state sensitive and need portability context.",
							"Partial: local host metadata is in the report, but not in a per-run sidecar schema.",
							"Runs from different host states can be pooled as if they were equivalent.",
							TRUE, 3, 3, "environment",
							"Source-span and browser scheduler ids",
							"Gutenberg source-span ids; V8 slices; task queue ids; protocol command timing; scheduler trace categories",
							"Needed only if OS counters do not explain the split and the claim moves to Chromium scheduler state.",
							"Partial: Gutenberg source spans exist; scheduler/runtime categories are not in the compact counter run.",
							"Browser-scheduler explanations would be unjoinable to the measured input windows.",
							FALSE, 4, 3, "browser ids"
						) %>%
							mutate(
								add_before_root_run = factor(
									if_else(add_before_root_run, "required before first root run", "after OS-counter split"),
									levels = c("required before first root run", "after OS-counter split")
								),
								label_x = case_when(
									plot_label == "retained key" ~ 5.12,
									plot_label == "timebase" ~ 4.68,
									plot_label == "sample ids" ~ 4.68,
									plot_label == "helper pid" ~ 5.12,
									plot_label == "renderer pid" ~ 4.68,
									TRUE ~ mechanism_value_score + 0.08
								),
								label_y = case_when(
									plot_label == "retained key" ~ 5.08,
									plot_label == "timebase" ~ 4.92,
									plot_label == "sample ids" ~ 5.24,
									plot_label == "helper pid" ~ 4.06,
									plot_label == "renderer pid" ~ 3.84,
									TRUE ~ join_blocker_score + 0.08
								)
							)

						cpu_qos_sidecar_mvp_plan <- tribble(
							~implementation_piece, ~phase_order, ~source_surface, ~required_change, ~first_validation, ~stop_condition, ~phase, ~implementation_burden_score, ~mechanism_unblock_score, ~observer_risk_score, ~plot_label,
							"Compact row manifest lock", 1,
							"typing-delay-cpu-qos-control-summary.csv; typing-delay-finite-cpu-model-*.csv",
							"Freeze the first sidecar manifest to no-CPU slow, ordinary/utility fast, background/maintenance slow, fresh finite, stale finite, and one matched no-helper control.",
							"The sidecar dry run reproduces the known class ordering before any privileged collector is attached.",
							"Stop if the manifest no longer separates the known fast and slow classes before counters are added.",
							"sidecar first", 1.8, 4.5, 2.0, "manifest",
							"Helper process wrapper", 2,
							"external CPU helper launch path used by task-end / CPU controls",
							"Record helper pid, process group, command, nice/taskpolicy/QoS policy, launch/start/end timestamps, CPU duration, exit status, and stderr/stdout paths for each retained-key window.",
							"Every helper-backed retained key joins to exactly one helper lifetime and policy row; no-helper rows explicitly record no helper.",
							"Stop if helper policy or lifetime can only be inferred from the run label.",
							"sidecar first", 2.6, 5.0, 3.0, "helper",
							"Retained key-window sidecar", 3,
							"delayRunSummaries records; EventDispatch/key event extraction",
							"Emit a stable window id with run id, delay, delay mode, sample index, retained/throwaway status, q50 inclusion, keydown/keypress/keyup enqueue times, EventDispatch start/end, and browser/host clock sync.",
							"100% of retained q50-contributing keys have key-window fields and match existing latency records.",
							"Stop before root collectors if retained-key joins are missing or alter q50 output.",
							"sidecar first", 2.8, 5.0, 3.0, "key windows",
							"Renderer/browser identity", 4,
							"Playwright browser/process metadata; CDP target/session metadata",
							"Record browser pid, renderer pid, main thread id if available, target id, frame id, browser revision, and page URL/document fixture metadata per run.",
							"Each retained key can be attributed to the foreground renderer that handled the input.",
							"Stop if powermetrics/trace would describe only browser-wide or wrong-process counters.",
							"sidecar first", 3.0, 4.8, 3.5, "renderer",
							"Collector placeholder schema", 5,
							"benchmark raw JSON and report extractor schema",
							"Before root collection, add collector run id placeholders, intended powermetrics plist path, trace path, sample interval, notification labels, and observer configuration fields.",
							"Sidecar-only artifacts contain all join columns that later root collector files will fill.",
							"Stop if adding collector fields forces an incompatible artifact schema or changes curated metrics.",
							"sidecar first", 3.2, 4.6, 3.5, "collector ids",
							"Sidecar-only acceptance run", 6,
							"compact CPU/QoS manifest with collectors disabled",
							"Run the compact manifest with the sidecar enabled and privileged collectors disabled.",
							"Class ordering survives, all retained windows join to helper and renderer fields, and sidecar overhead is bounded by matched no-sidecar rows.",
							"Do not run root powermetrics if the sidecar alone perturbs the benchmark.",
							"acceptance gate", 3.8, 5.0, 4.0, "acceptance",
							"Root powermetrics triage", 7,
							"powermetrics tasks/cpu_power plist output",
							"After the sidecar passes, collect 100ms plist samples with tasks, cpu_power, thermal, sfi, pstates, process QoS/tier/AMP/IPC/wait-time fields.",
							"One sampled OS state predicts ordinary/utility fast rows and finite decay while absent from no-CPU and background/maintenance slow rows.",
							"Escalate to root trace if frequency/residency/QoS counters do not separate the rows or sampling misses key windows.",
							"root counters", 4.4, 5.0, 5.0, "powermetrics",
							"Root system trace escalation", 8,
							"trace record scheduling/qos/processor-selection plans",
							"Only after powermetrics is insufficient, record scheduler/QoS trace rows with the same sidecar windows and notification labels.",
							"Runnable latency, processor selection, wakeup, or effective QoS explains the residual after matching powermetrics state.",
							"Do not claim Darwin scheduler/QoS placement if trace overhead changes class ordering or counters still do not join per key.",
							"root counters", 4.8, 4.6, 5.0, "system trace",
							"Browser/cache fallback", 9,
							"Chromium scheduler trace; lower-level renderer counters",
							"Only after OS counters fail, add browser scheduler/task-queue traces or lower-level renderer counters joined to the same key windows.",
							"Browser queue/cache/stall state predicts residual latency after OS frequency, residency, and scheduler state are controlled.",
							"Keep the mechanism unnamed if browser/cache rows need unrelated explanations or observer controls fail.",
							"deferred", 5.0, 3.8, 4.5, "browser/cache"
						) %>%
							mutate(
								phase = factor(
									phase,
									levels = c("sidecar first", "acceptance gate", "root counters", "deferred")
								),
								label_x = implementation_burden_score + case_when(
									plot_label == "manifest" ~ 0.12,
									plot_label == "helper" ~ 0.16,
									plot_label == "key windows" ~ 0.16,
									plot_label == "renderer" ~ 0.16,
									plot_label == "collector ids" ~ 0.16,
									plot_label == "acceptance" ~ 0.16,
									plot_label == "powermetrics" ~ -0.98,
									plot_label == "system trace" ~ -0.94,
									TRUE ~ -0.85
								),
								label_y = mechanism_unblock_score + case_when(
									plot_label == "manifest" ~ -0.12,
									plot_label == "helper" ~ 0.08,
									plot_label == "key windows" ~ -0.12,
									plot_label == "renderer" ~ -0.18,
									plot_label == "collector ids" ~ -0.20,
									plot_label == "acceptance" ~ 0.10,
									plot_label == "powermetrics" ~ -0.14,
									plot_label == "system trace" ~ -0.18,
									TRUE ~ 0.14
								)
							)

						cpu_qos_counter_decision_tree <- tribble(
							~stage, ~stage_order, ~question_answered, ~required_inputs, ~advance_condition, ~fallback_condition, ~mechanism_value_score, ~collection_burden_score, ~decision, ~plot_label,
							"Sidecar-only dry run", 1,
							"Can every retained key be joined to helper, browser, and collector windows without changing the benchmark result?",
							"retained-key id; input/EventDispatch timebase; helper pid/policy; renderer pid; collector file placeholders",
							"100% of retained keys have join fields, and the compact q50 class ordering matches the existing uninstrumented run.",
							"Do not run root counters yet; fix join fields or observer overhead first.",
							5, 2, "do first", "sidecar",
							"Root powermetrics compact rows", 2,
							"Do frequency, cluster residency, process QoS, AMP counters, or thermal/power state distinguish fast and slow classes?",
							"sidecar join plus no-CPU slow, ordinary/utility fast, background/maintenance slow, fresh finite, and stale finite rows",
							"One sampled OS state predicts ordinary/utility fast rows and finite decay while absent from no-CPU and background/maintenance slow rows.",
							"If sampling cadence misses key windows or counters do not separate rows, add system trace.",
							5, 4, "first root run", "powermetrics",
							"Root system trace split", 3,
							"If powermetrics is insufficient, do runnable latency, QoS placement, wakeup timing, or processor selection explain the rows?",
							"same compact rows with trace notifications joined to retained keys",
							"Scheduler/QoS timing predicts the same fast/slow split after accounting for frequency and residency.",
							"If trace overhead changes class ordering or scheduler state still does not separate rows, test browser scheduler state.",
							5, 5, "conditional", "trace",
							"Chromium scheduler trace", 4,
							"After OS state is controlled, do browser queue, task priority, V8, or runtime slices explain the residual?",
							"matched browser runtime/scheduler categories plus source spans and OS-counter alignment",
							"Browser queue/task state predicts residual latency when OS frequency/residency/QoS does not.",
							"If browser trace duplicates the OS split or perturbs the path, keep the mechanism at the OS-counter layer.",
							4, 4, "conditional", "browser",
							"Cache or memory fallback", 5,
							"If OS and browser scheduling are both insufficient, is the remaining split a cache/memory hierarchy effect?",
							"lower-level counters or specialized profiler support joined to retained EventDispatch windows",
							"Renderer stall or miss ratios separate fast and slow rows without matching frequency, QoS, or scheduler differences.",
							"Do not claim cache/memory from JS timing alone.",
							3, 5, "fallback only", "cache",
							"Mechanism report gate", 6,
							"Is there one named state variable that predicts all discriminating rows?",
							"joined per-key table containing all successful compact rows and observer controls",
							"No-CPU slow, ordinary/utility fast, background/maintenance slow, and finite decay all follow the same recorded state.",
							"If only medians agree or different row families need unrelated explanations, leave the mechanism unnamed.",
							5, 3, "report gate", "gate"
						) %>%
							mutate(
								stage = factor(stage, levels = stage),
								decision = factor(
									decision,
									levels = c("do first", "first root run", "conditional", "fallback only", "report gate")
								)
							)

						cpu_qos_claim_ladder_audit <- tribble(
							~claim, ~claim_order, ~allowed_claim, ~current_evidence, ~blocked_overclaim, ~required_next_evidence, ~evidence_score, ~validation_burden_score, ~overclaim_risk_score, ~decision, ~plot_label,
							"Benchmark boundary", 1,
							"Ordinary/utility CPU state modulates the measured Gutenberg input path; background/maintenance CPU does not.",
							"Near-key no-CPU controls stay slow at median p50 24.3ms, continuous ordinary/utility CPU is fast at 9.7ms, and background/maintenance CPU is slow at 24.2ms.",
							"Naming P-core residency, frequency, cache, scheduler QoS, or Chromium scheduler state from aggregate p50 rows.",
							"None for the boundary claim; a sidecar plus privileged counters for the named mechanism.",
							5, 1, 2, "locally supported", "CPU boundary",
							"No-op or timer callback explanation", 2,
							"A nearby no-op callback, delayed task, IPC command, idle child, or worker lifetime is not sufficient.",
							"Six near-key no-CPU controls remain slow, with p50 range 22.2-24.6ms.",
							"Explaining the fast band as merely a callback existing before the key.",
							"No more no-CPU rows unless a concrete new browser subsystem is targeted.",
							5, 1, 1, "locally ruled out", "no-op tasks",
							"Generic CPU burn explanation", 3,
							"Generic external CPU activity is not sufficient; the effect is policy-sensitive.",
							"Background and maintenance QoS CPU controls consume CPU but remain slow at median p50 24.2ms.",
							"Claiming that any load, any process activity, or any warm CPU is enough.",
							"Privileged counters only to identify the lower-level policy or hardware state.",
							5, 1, 2, "locally ruled out", "generic CPU",
							"Finite CPU duration/proximity", 4,
							"Finite CPU work has a descriptive duration and recency relationship with the next retained key.",
							"The two-variable finite-burst model has R^2 = 0.71 with expected coefficient signs.",
							"Treating the regression as proof of frequency, scheduler, cache, or browser queue state.",
							"Join finite rows to per-key frequency/residency, scheduler, wakeup, and browser-task counters.",
							4, 3, 3, "descriptive only", "finite decay",
							"P-core or cluster frequency/residency", 5,
							"Still an open candidate mechanism.",
							"Ordinary/utility versus background/maintenance policy split is consistent with a power or residency boundary, but current artifacts do not contain residency/frequency counters.",
							"Claiming P-core, cluster, frequency, or power-state causality from browser timing alone.",
							"Sidecar dry run, then root powermetrics joined to retained key windows.",
							2, 4, 5, "needs powermetrics", "P-core / freq",
							"Darwin scheduler or QoS placement", 6,
							"Still an open candidate mechanism.",
							"The split tracks ordinary/utility versus background/maintenance policy more closely than Unix nice or taskpolicy latency/throughput tiers.",
							"Claiming scheduler or QoS placement without runnable latency, wakeup, core-selection, and effective-QoS records.",
							"Root trace only after powermetrics cannot explain the split.",
							3, 5, 5, "needs trace", "scheduler / QoS",
							"Cache or memory hierarchy", 7,
							"Fallback candidate only after OS scheduler and power-state counters are insufficient.",
							"Gutenberg's broad JS/data/RichText path could be memory-sensitive, but external child CPU controls mean the mechanism cannot require warming Gutenberg objects directly.",
							"Claiming cache or memory causality from the local JS timing shape.",
							"Lower-level renderer counters joined to retained EventDispatch windows after OS and browser scheduling are controlled.",
							1, 5, 4, "fallback only", "cache / memory",
							"Chromium scheduler state", 8,
							"Open only after OS counters fail to explain the split.",
							"Runtime-protocol and CPU/QoS controls show a browser/runtime boundary below Gutenberg source spans, but the current CPU/QoS rows do not include scheduler trace categories.",
							"Naming V8, browser task queue, or scheduler state before OS power/QoS state is matched.",
							"Trace-off protocol sidecar first; scheduler/task-queue categories after OS counter alignment.",
							2, 5, 4, "after OS counters", "browser scheduler",
							"Product optimization conclusion", 9,
							"Keep product mitigation separate from system-mechanism naming.",
							"Native controls move less than 1ms while Gutenberg moves by many milliseconds; Gutenberg fanout supplies the scale.",
							"Treating a system-state mechanism as a source-level fix, or treating source fanout as proof of the system mechanism.",
							"Selector/subscriber prototypes and workload replay for product lag; OS counters for the benchmark artifact.",
							4, 3, 4, "separate product work", "product work",
							"Mechanism report update", 10,
							"Do not name the exact mechanism until one recorded state predicts all discriminating rows.",
							"The compact rows and join contract are selected, but the joined per-key counter table does not exist yet.",
							"Updating the report from class medians, one successful row family, or unrelated explanations for separate row families.",
							"Joined per-key table covering no-CPU slow, ordinary/utility fast, background/maintenance slow, finite fresh/stale, and observer controls.",
							5, 5, 5, "report gate", "report gate"
						) %>%
							mutate(
								decision = factor(
									decision,
									levels = c(
										"locally supported",
										"locally ruled out",
										"descriptive only",
										"needs powermetrics",
										"needs trace",
										"after OS counters",
										"fallback only",
										"separate product work",
										"report gate"
									)
								),
								label_x = case_when(
									plot_label == "no-op tasks" ~ 1.18,
									plot_label == "generic CPU" ~ 1.18,
									plot_label == "CPU boundary" ~ 1.18,
									plot_label == "finite decay" ~ 3.10,
									plot_label == "product work" ~ 2.80,
									plot_label == "P-core / freq" ~ 3.68,
									plot_label == "scheduler / QoS" ~ 4.58,
									plot_label == "cache / memory" ~ 4.55,
									plot_label == "browser scheduler" ~ 4.54,
									TRUE ~ validation_burden_score + 0.1
								),
								label_y = case_when(
									plot_label == "no-op tasks" ~ 0.84,
									plot_label == "generic CPU" ~ 1.68,
									plot_label == "CPU boundary" ~ 2.36,
									plot_label == "finite decay" ~ 2.66,
									plot_label == "product work" ~ 4.32,
									plot_label == "P-core / freq" ~ 5.15,
									plot_label == "scheduler / QoS" ~ 5.23,
									plot_label == "cache / memory" ~ 3.78,
									plot_label == "browser scheduler" ~ 4.33,
									TRUE ~ overclaim_risk_score + 0.1
								)
							)

					write_csv(
						system_mechanism_matrix,
						file.path(data_dir, "typing-delay-system-mechanism-falsification-matrix.csv")
				)
			write_csv(
				cpu_qos_next_probe_audit,
				file.path(data_dir, "typing-delay-cpu-qos-next-probe-audit.csv")
			)
				write_csv(
					cpu_qos_counter_contract_audit,
					file.path(data_dir, "typing-delay-cpu-qos-counter-contract-audit.csv")
				)
					write_csv(
						cpu_qos_counter_runset_contract_audit,
						file.path(data_dir, "typing-delay-cpu-qos-counter-runset-contract-audit.csv")
					)
					write_csv(
						cpu_qos_local_counter_feasibility_audit,
						file.path(data_dir, "typing-delay-cpu-qos-local-counter-feasibility-audit.csv")
					)
						write_csv(
							cpu_qos_counter_first_run_plan,
							file.path(data_dir, "typing-delay-cpu-qos-counter-first-run-plan.csv")
						)
							write_csv(
								cpu_qos_counter_join_contract %>% select(-label_x, -label_y),
								file.path(data_dir, "typing-delay-cpu-qos-counter-join-contract.csv")
							)
							write_csv(
								cpu_qos_sidecar_mvp_plan %>% select(-label_x, -label_y),
								file.path(data_dir, "typing-delay-cpu-qos-sidecar-mvp-plan.csv")
							)
						write_csv(
							cpu_qos_counter_decision_tree,
							file.path(data_dir, "typing-delay-cpu-qos-counter-decision-tree.csv")
						)
						write_csv(
							cpu_qos_claim_ladder_audit %>% select(-label_x, -label_y),
							file.path(data_dir, "typing-delay-cpu-qos-claim-ladder-audit.csv")
						)

			save_plot(
				ggplot(
				system_mechanism_matrix,
				aes(
					evidence_strength,
					fct_reorder(candidate_theory_wrapped, theory_order, .desc = TRUE),
					color = status,
					shape = status
				)
			) +
				geom_point(size = 4.3, alpha = 0.95) +
				scale_color_brewer(type = "qual", palette = "Set1", drop = FALSE) +
				scale_shape_manual(values = c(
					`ruled out` = 4,
					`ruled out for large cliff` = 13,
					`supported boundary` = 16,
					`still open` = 1
				), drop = FALSE) +
				scale_x_continuous(breaks = 1:5, limits = c(1, 5.4)) +
				labs(
					title = "Most broad system-level explanations are already ruled out",
					subtitle = "Qualitative evidence matrix from visual, native, CPU/QoS, and taskpolicy controls",
					x = "Evidence strength from existing controls (1-5)",
					y = NULL,
					color = "Status",
					shape = "Status"
				),
				"129-system-mechanism-falsification-matrix.png",
				width = 11.5,
				height = 7.3
			)

				save_plot(
					ggplot(
						cpu_qos_local_counter_feasibility_audit,
						aes(mechanism_value_score, collection_blocker_score, color = available_in_session, shape = available_in_session)
					) +
						geom_point(size = 3.7, alpha = 0.92) +
						geom_text(
							aes(label = plot_label),
							nudge_x = 0.08,
							nudge_y = 0.08,
							size = 3,
							show.legend = FALSE,
							check_overlap = TRUE
						) +
						scale_color_brewer(type = "qual", palette = "Dark2", drop = FALSE) +
						scale_shape_manual(values = c(16, 17, 15, 8, 4), drop = FALSE) +
						scale_x_continuous(breaks = 1:5, limits = c(1, 5.7)) +
						scale_y_continuous(breaks = 1:5, limits = c(1, 5.5)) +
						labs(
							title = "CPU/QoS counters are available, but the decisive lanes are privileged",
							subtitle = "Higher x means more useful for the mechanism; higher y means more local collection friction in this session",
							x = "mechanism value (1 = weak, 5 = decisive)",
							y = "collection blocker (1 = low, 5 = high)",
							color = "Local state",
							shape = "Local state"
						),
					"172-cpu-qos-counter-feasibility.png",
					width = 12,
					height = 7
				)

					save_plot(
						ggplot(
							cpu_qos_counter_first_run_plan,
						aes(phase_order, phase, color = implementation_status, shape = implementation_status)
					) +
						geom_point(size = 4, alpha = 0.95) +
						geom_text(
							aes(label = plot_label),
							nudge_x = 0.08,
							size = 3,
							show.legend = FALSE,
							check_overlap = TRUE
						) +
						scale_color_brewer(type = "qual", palette = "Set2", drop = FALSE) +
						scale_shape_manual(values = c(16, 17, 15, 8), drop = FALSE) +
						scale_x_continuous(breaks = 1:5, limits = c(0.8, 5.8)) +
						labs(
							title = "The next CPU/QoS run should be a compact counter ladder",
							subtitle = "Do not add broad JS rows until the sidecar and privileged counter lanes can distinguish the remaining theories",
							x = "collection phase",
							y = NULL,
							color = "Implementation state",
							shape = "Implementation state"
						),
					"173-cpu-qos-counter-first-run-plan.png",
						width = 12,
						height = 6.8
					)

