				use_select_on_store_change_count_p50 = "sync onStoreChange",
				use_select_update_value_count_p50 = "sync updateValue",
				use_select_map_select_count_p50 = "sync mapSelect"
			),
			outcome = factor(
				outcome,
				levels = rev(c(
					"woken useSelect.onChange",
					"queued async updates",
					"sync onStoreChange",
					"sync updateValue",
					"sync mapSelect"
				))
			),
			intervention = factor(
				intervention,
				levels = rev(c(
					"normal marker",
