save_plot(
	ggplot(
		open_question_gate_quality,
		aes(reorder(gate_label, overall_gate_risk), overall_gate_risk, fill = dominant_risk)
	) +
		geom_col(width = 0.72) +
		coord_flip() +
		scale_fill_brewer(type = "qual", palette = "Set2", name = "Dominant risk") +
