				"FIXTURE",
				"MODE",
				"HOLD",
				"TIMER",
				"NOOP",
				"WORK",
				"EDISP",
				"FF",
				"WAIT",
				"RT",
				"PAYLOAD",
				"VISUAL",
				"FANOUT",
