if (length(open_question_local_gate_tail_veto_rows) > 0) {
	open_question_local_gate_tail_veto <- bind_rows(open_question_local_gate_tail_veto_rows) %>%
		mutate(
			veto_result = factor(
				veto_result,
				levels = c("no q50/tail veto", "variance caution only", "q50/tail pass", "p90 caution", "q50 or mean veto", "readiness veto", "semantic gate only", "reference")
			),
			gate_label = str_wrap(local_gate, width = 24)
		)

	open_question_local_gate_tail_veto_long <- open_question_local_gate_tail_veto %>%
		transmute(
			local_gate,
			gate_label,
			veto_result,
			q50_delta_score = case_when(is.na(q50_delta_ms) ~ NA_real_, q50_delta_ms <= 5 ~ 1, TRUE ~ 5),
			mean_delta_score = case_when(is.na(mean_delta_ms) ~ NA_real_, mean_delta_ms <= 5 ~ 1, TRUE ~ 5),
			p90_delta_score = case_when(is.na(p90_delta_ms) ~ NA_real_, p90_delta_ms <= 5 ~ 1, p90_delta_ms <= 15 ~ 3, TRUE ~ 5),
			non_q50_blocker_score = case_when(
				veto_result %in% c("no q50/tail veto", "q50/tail pass") ~ 1,
				veto_result %in% c("variance caution only", "p90 caution", "semantic gate only") ~ 3,
				TRUE ~ 5
			)
		) %>%
		pivot_longer(
			cols = c(q50_delta_score, mean_delta_score, p90_delta_score, non_q50_blocker_score),
			names_to = "veto_dimension",
			values_to = "score"
		) %>%
		mutate(
			veto_dimension = recode(
				veto_dimension,
				q50_delta_score = "q50 risk",
				mean_delta_score = "mean risk",
				p90_delta_score = "p90 risk",
				non_q50_blocker_score = "non-q50 blocker"
			),
			veto_dimension = factor(veto_dimension, levels = c("q50 risk", "mean risk", "p90 risk", "non-q50 blocker"))
		)

	write_csv(
		open_question_local_gate_tail_veto,
		file.path(data_dir, "typing-delay-open-question-local-gate-tail-veto.csv")
	)
	write_csv(
		open_question_local_gate_tail_veto_long,
		file.path(data_dir, "typing-delay-open-question-local-gate-tail-veto-long.csv")
	)

	save_plot(
		ggplot(open_question_local_gate_tail_veto_long, aes(veto_dimension, gate_label, fill = score)) +
			geom_tile(color = "white", linewidth = 0.42) +
			geom_text(aes(label = if_else(is.na(score), "n/a", as.character(score))), size = 3, color = "grey15") +
			scale_fill_distiller(type = "seq", palette = "OrRd", direction = 1, name = "Risk", na.value = "grey88") +
			labs(
				title = "Non-q50 checks narrow the remaining local open questions",
				subtitle = "Startup wait has no q50/mean/p90 veto; pattern wait has a p90 caveat; selector work is gated by semantics, not latency",
				x = "Check",
				y = "Local gate"
			) +
			theme_minimal(base_size = 12) +
			theme(legend.position = "bottom", axis.text.x = element_text(angle = 20, hjust = 1)),
		"281-open-question-local-gate-tail-veto.png",
		width = 11.8,
		height = 5.6
	)
}

open_question_startup_sequence_path <- file.path(data_dir, "typing-delay-ci-comparable-start-wait-keypress-distribution-summary.csv")
open_question_pattern_short_runs_path <- file.path(data_dir, "typing-delay-site-pattern-short-wait-exact-runs.csv")
open_question_caveat_disposition_rows <- list()

if (file.exists(open_question_startup_sequence_path)) {
	open_question_startup_sequence_distribution <- read_csv(open_question_startup_sequence_path, show_col_types = FALSE) %>%
		mutate(
			key_position_class = case_when(
				keypress_index == 1 ~ "discarded first key",
				keypress_index == 2 ~ "first retained key",
				keypress_index >= 3 ~ "steady retained keys",
				TRUE ~ "other"
			)
		)

	open_question_startup_sequence_summary <- open_question_startup_sequence_distribution %>%
		group_by(startup_wait_ms, key_position_class) %>%
		summarize(
			keypress_indices = if_else(n() == 1L, as.character(first(keypress_index)), paste0(min(keypress_index), "-", max(keypress_index))),
			n_key_positions = n(),
			latency_p50_ms = median(latency_p50_ms, na.rm = TRUE),
			latency_p90_ms = median(latency_p90_ms, na.rm = TRUE),
			latency_sd_ms = median(latency_sd_ms, na.rm = TRUE),
			max_position_p90_ms = max(latency_p90_ms, na.rm = TRUE),
			.groups = "drop"
		) %>%
		mutate(
			wait_label = case_when(
				startup_wait_ms == 0 ~ "0",
				startup_wait_ms < 1000 ~ paste0(startup_wait_ms, "ms"),
				startup_wait_ms %% 1000 == 0 ~ paste0(startup_wait_ms / 1000, "s"),
				TRUE ~ paste0(startup_wait_ms, "ms")
			),
			wait_label = factor(wait_label, levels = unique(wait_label[order(startup_wait_ms)])),
			key_position_class = factor(key_position_class, levels = c("discarded first key", "first retained key", "steady retained keys"))
		)

	open_question_startup_sequence_wide <- open_question_startup_sequence_summary %>%
		select(startup_wait_ms, key_position_class, latency_p50_ms, latency_p90_ms, max_position_p90_ms) %>%
		pivot_wider(
			names_from = key_position_class,
			values_from = c(latency_p50_ms, latency_p90_ms, max_position_p90_ms),
			names_glue = "{.value}_{str_replace_all(key_position_class, '[^A-Za-z0-9]+', '_')}"
		) %>%
		mutate(
			first_retained_vs_steady_p50_gap_ms = latency_p50_ms_first_retained_key - latency_p50_ms_steady_retained_keys,
			discarded_vs_steady_p50_gap_ms = latency_p50_ms_discarded_first_key - latency_p50_ms_steady_retained_keys,
			first_retained_vs_steady_p90_gap_ms = latency_p90_ms_first_retained_key - latency_p90_ms_steady_retained_keys,
			steady_retained_max_p90_ms = max_position_p90_ms_steady_retained_keys,
			wait_label = case_when(
				startup_wait_ms == 0 ~ "0",
				startup_wait_ms < 1000 ~ paste0(startup_wait_ms, "ms"),
				startup_wait_ms %% 1000 == 0 ~ paste0(startup_wait_ms / 1000, "s"),
				TRUE ~ paste0(startup_wait_ms, "ms")
			),
			wait_label = factor(wait_label, levels = wait_label[order(startup_wait_ms)]),
			sequence_disposition = case_when(
				first_retained_vs_steady_p50_gap_ms > 8 & startup_wait_ms == 0 ~ "same sequence cost; no startup-wait fix",
				first_retained_vs_steady_p50_gap_ms > 8 ~ "same sequence cost",
				TRUE ~ "small sequence cost"
			)
		)

	write_csv(
		open_question_startup_sequence_summary,
		file.path(data_dir, "typing-delay-open-question-startup-sequence-summary.csv")
	)
	write_csv(
		open_question_startup_sequence_wide,
		file.path(data_dir, "typing-delay-open-question-startup-sequence-wide.csv")
	)

	save_plot(
		ggplot(
			open_question_startup_sequence_summary,
			aes(wait_label, latency_p50_ms, color = key_position_class)
		) +
			geom_point(size = 2.8, alpha = 0.9, position = position_dodge(width = 0.45)) +
			scale_color_brewer(type = "qual", palette = "Dark2", name = "Key position") +
			labs(
				title = "Startup early-key caveat is sequence-position cost, not startup-wait benefit",
				subtitle = "The first retained key is slow at every startup wait; steady retained keys stay near the low band",
				x = "Extra startup wait after editor setup",
				y = "Per-position p50 latency (ms)"
			) +
			theme_minimal(base_size = 12) +
			theme(legend.position = "bottom"),
		"282-open-question-startup-sequence-position.png",
		width = 12.8,
		height = 7.2
	)

	open_question_startup_sequence_zero <- open_question_startup_sequence_wide %>% filter(startup_wait_ms == 0)
	open_question_startup_sequence_reference <- open_question_startup_sequence_wide %>% filter(startup_wait_ms == 1000)
	if (nrow(open_question_startup_sequence_zero) > 0 && nrow(open_question_startup_sequence_reference) > 0) {
		open_question_caveat_disposition_rows <- append(
			open_question_caveat_disposition_rows,
			list(
				tibble(
					caveat = "Startup early-key variance",
					best_current_row = "0ms startup wait",
					decisive_detail = sprintf(
						"first retained vs steady p50 gap %.1fms at 0ms and %.1fms at 1s; discarded first key is already outside retained metric",
						open_question_startup_sequence_zero$first_retained_vs_steady_p50_gap_ms,
						open_question_startup_sequence_reference$first_retained_vs_steady_p50_gap_ms
					),
					disposition = "split metric, not wait",
					can_change_current_action = "no",
					remaining_evidence = "report first retained and idle-return separately if that user experience matters",
					decision_pressure = 2,
					claim_expansion_pressure = 3
				)
			)
		)
	}
}

if (file.exists(open_question_pattern_short_runs_path)) {
	open_question_pattern_short_runs <- read_csv(open_question_pattern_short_runs_path, show_col_types = FALSE)
	open_question_pattern_reference_runs <- open_question_pattern_short_runs %>%
		filter(measurement_idle_wait_ms == 1000)
	open_question_pattern_reference_p50_median <- median(open_question_pattern_reference_runs$p50_ms, na.rm = TRUE)
	open_question_pattern_reference_p90_median <- median(open_question_pattern_reference_runs$p90_ms, na.rm = TRUE)
	open_question_pattern_reference_p90_max <- max(open_question_pattern_reference_runs$p90_ms, na.rm = TRUE)

	open_question_pattern_tail_tradeoff <- open_question_pattern_short_runs %>%
		group_by(wait_ms = measurement_idle_wait_ms) %>%
		summarize(
			runs = n(),
			median_p50_ms = median(p50_ms, na.rm = TRUE),
			median_mean_ms = median(mean_ms, na.rm = TRUE),
			median_p90_ms = median(p90_ms, na.rm = TRUE),
			p50_iqr_ms = IQR(p50_ms, na.rm = TRUE),
			p90_iqr_ms = IQR(p90_ms, na.rm = TRUE),
			max_p90_ms = max(p90_ms, na.rm = TRUE),
			runs_p50_below_1000_median = sum(p50_ms < open_question_pattern_reference_p50_median, na.rm = TRUE),
			runs_p90_above_1000_median = sum(p90_ms > open_question_pattern_reference_p90_median, na.rm = TRUE),
			runs_p90_above_1000_max = sum(p90_ms > open_question_pattern_reference_p90_max, na.rm = TRUE),
			.groups = "drop"
		) %>%
		left_join(
			read_csv(open_question_pattern_boundary_path, show_col_types = FALSE) %>%
				select(wait_ms = waitMs, readiness_boundary_hit_rate, wait_resource_plateau_rate),
			by = "wait_ms"
		) %>%
		mutate(
			q50_delta_vs_1000ms = median_p50_ms - open_question_pattern_reference_p50_median,
			p90_delta_vs_1000ms = median_p90_ms - open_question_pattern_reference_p90_median,
			wait_label = case_when(
				wait_ms == 0 ~ "0",
				wait_ms < 1000 ~ paste0(wait_ms, "ms"),
				wait_ms %% 1000 == 0 ~ paste0(wait_ms / 1000, "s"),
				TRUE ~ paste0(wait_ms, "ms")
			),
			wait_label = factor(wait_label, levels = wait_label[order(wait_ms)]),
			tradeoff_class = case_when(
				wait_ms == 1000 ~ "reference",
				readiness_boundary_hit_rate < 1 | wait_resource_plateau_rate < 1 ~ "readiness veto",
				q50_delta_vs_1000ms <= 0 & p90_delta_vs_1000ms <= 0 ~ "q50 and p90 improve",
				q50_delta_vs_1000ms <= 0 & p90_delta_vs_1000ms > 0 ~ "q50 win, p90 cost",
				TRUE ~ "no q50 win"
			),
			tradeoff_class = factor(tradeoff_class, levels = c("q50 and p90 improve", "q50 win, p90 cost", "no q50 win", "readiness veto", "reference"))
		)

	open_question_pattern_tail_tradeoff_runs <- open_question_pattern_short_runs %>%
		mutate(
			wait_label = case_when(
				measurement_idle_wait_ms == 0 ~ "0",
				measurement_idle_wait_ms < 1000 ~ paste0(measurement_idle_wait_ms, "ms"),
				measurement_idle_wait_ms %% 1000 == 0 ~ paste0(measurement_idle_wait_ms / 1000, "s"),
				TRUE ~ paste0(measurement_idle_wait_ms, "ms")
			),
			wait_label = factor(wait_label, levels = open_question_pattern_tail_tradeoff$wait_label[order(open_question_pattern_tail_tradeoff$wait_ms)]),
			wait_class = if_else(measurement_idle_wait_ms == 500, "500ms candidate", if_else(measurement_idle_wait_ms == 1000, "1000ms reference", "other wait"))
		)

	write_csv(
		open_question_pattern_tail_tradeoff,
		file.path(data_dir, "typing-delay-open-question-pattern-p90-tradeoff.csv")
	)
	write_csv(
		open_question_pattern_tail_tradeoff_runs,
		file.path(data_dir, "typing-delay-open-question-pattern-p90-tradeoff-runs.csv")
	)

	save_plot(
		ggplot(open_question_pattern_tail_tradeoff_runs, aes(p50_ms, p90_ms, color = wait_class)) +
			geom_vline(xintercept = open_question_pattern_reference_p50_median, color = "grey55", linewidth = 0.35, linetype = "dashed") +
			geom_hline(yintercept = open_question_pattern_reference_p90_median, color = "grey55", linewidth = 0.35, linetype = "dashed") +
			geom_point(alpha = 0.82, size = 2.8) +
			scale_color_brewer(type = "qual", palette = "Set1", name = "Run class") +
			labs(
				title = "Pattern 500ms row buys q50 at the cost of a p90 caveat",
				subtitle = "Dashed lines are the 1000ms median p50 and p90; the candidate is not a clean tail improvement",
				x = "Run q50 (ms)",
				y = "Run p90 (ms)"
			) +
			theme_minimal(base_size = 12) +
			theme(legend.position = "bottom"),
		"283-open-question-pattern-p90-tradeoff.png",
		width = 12.4,
		height = 7.2
	)

	open_question_pattern_500_tradeoff <- open_question_pattern_tail_tradeoff %>% filter(wait_ms == 500)
	if (nrow(open_question_pattern_500_tradeoff) > 0) {
		open_question_caveat_disposition_rows <- append(
			open_question_caveat_disposition_rows,
			list(
				tibble(
					caveat = "Pattern 500ms p90 caveat",
					best_current_row = "500ms fixed wait",
					decisive_detail = sprintf(
						"q50 delta %.1fms, p90 delta %.1fms; %d/%d candidate runs exceed 1s median p90 and %d exceed 1s max p90",
						open_question_pattern_500_tradeoff$q50_delta_vs_1000ms,
						open_question_pattern_500_tradeoff$p90_delta_vs_1000ms,
						open_question_pattern_500_tradeoff$runs_p90_above_1000_median,
						open_question_pattern_500_tradeoff$runs,
						open_question_pattern_500_tradeoff$runs_p90_above_1000_max
					),
					disposition = "candidate with tail gate",
					can_change_current_action = "yes, for rollout wording",
					remaining_evidence = "CI/mac/container target topology and p90 acceptance policy",
					decision_pressure = 4,
					claim_expansion_pressure = 4
				)
			)
		)
	}
}

if (length(open_question_caveat_disposition_rows) > 0) {
	open_question_caveat_disposition <- bind_rows(open_question_caveat_disposition_rows) %>%
		mutate(
			caveat_label = str_wrap(caveat, width = 28),
			disposition = factor(disposition, levels = c("split metric, not wait", "candidate with tail gate"))
		)

	open_question_caveat_disposition_long <- open_question_caveat_disposition %>%
		transmute(
			caveat,
			caveat_label,
			disposition,
			decision_pressure,
			claim_expansion_pressure,
			action_change_score = if_else(can_change_current_action == "yes, for rollout wording", 4, 1)
		) %>%
		pivot_longer(
			cols = c(decision_pressure, claim_expansion_pressure, action_change_score),
			names_to = "dimension",
			values_to = "score"
		) %>%
		mutate(
			dimension = recode(
				dimension,
				decision_pressure = "decision pressure",
				claim_expansion_pressure = "claim pressure",
				action_change_score = "can change action"
			),
			dimension = factor(dimension, levels = c("decision pressure", "claim pressure", "can change action"))
		)

	write_csv(
		open_question_caveat_disposition,
		file.path(data_dir, "typing-delay-open-question-caveat-disposition.csv")
	)
	write_csv(
		open_question_caveat_disposition_long,
		file.path(data_dir, "typing-delay-open-question-caveat-disposition-long.csv")
	)

	save_plot(
		ggplot(open_question_caveat_disposition_long, aes(dimension, caveat_label, fill = score)) +
			geom_tile(color = "white", linewidth = 0.42) +
			geom_text(aes(label = score), size = 3, color = "grey15") +
			scale_fill_distiller(type = "seq", palette = "YlGnBu", direction = 1, name = "Score") +
			labs(
				title = "Remaining local caveats split into metric wording and rollout gates",
				subtitle = "Startup early-key cost should be reported separately; pattern p90 can still change rollout wording",
				x = "Dimension",
				y = "Caveat"
			) +
			theme_minimal(base_size = 12) +
			theme(legend.position = "bottom", axis.text.x = element_text(angle = 20, hjust = 1)),
		"284-open-question-caveat-disposition.png",
		width = 11.6,
		height = 5.4
	)
}

open_question_100_pass_axes <- tribble(
	~pressure_axis, ~challenge, ~repeat_failure_mode, ~useful_artifact_class,
	"decision", "What would change a near-term engineering action?", "Restating the same recommendation without naming the action boundary.", "decision gate",
	"counterexample", "What counterexample would overturn the current wording?", "Inventing a vague possible failure without a decisive observation.", "falsifier",
	"triangulation", "What independent artifact would corroborate or conflict?", "Adding another same-harness row where a different observer is required.", "independent artifact",
	"closure", "What exact field closes the question?", "Treating uncertainty as low sample count when the missing field is absent.", "closing field",
	"intervention", "What controlled intervention separates mechanisms?", "Changing multiple knobs and calling the result causal.", "controlled intervention",
	"policy", "What external rule turns an artifact into pass/fail?", "Calling local q50 a policy decision.", "policy join",
	"tail", "Can q50 survive mean, p90, first-key, or failure vetoes?", "Averaging away retained-tail or first-key caveats.", "tail veto",
	"source", "Is the source or behavior gate strong enough before timing?", "Using aggregate p50 to prove semantic safety.", "behavior/source gate",
	"topology", "Does the target runner/spec lane preserve the local result?", "Shipping a local candidate without target-topology checks.", "topology validation",
	"claim", "Which wording is still blocked by missing observers?", "Broadening a scoped benchmark fact into a product or mechanism claim.", "claim boundary"
)

open_question_100_pass_question_pool <- open_question_minimum_decisive_artifact %>%
	select(
		question_family,
		artifact_lane,
		owner,
		minimum_decisive_artifact,
		first_field_to_check,
		pass_condition,
		fail_condition,
		waste_to_avoid,
		mixed_result_action,
		decision_value,
		artifact_cost,
		same_harness_futility,
		ambiguity_if_missing,
		artifact_readiness,
		stop_if_no_trigger
	) %>%
	left_join(
		open_question_residual_uncertainty_budget %>%
			select(
				question_family,
				budget_class,
				local_reducible_score,
				external_reducible_score,
				claim_boundary_score,
				decision_urgency_score,
				wrong_action_risk,
				stop_confidence
			),
		by = "question_family"
	) %>%
	mutate(
		evidence_lane = case_when(
			artifact_lane == "trigger-only" ~ "trigger-only recheck",
			str_detect(question_family, "Startup|Pattern") ~ "target-topology gate",
			str_detect(question_family, "Selector") ~ "behavior/source gate",
			str_detect(question_family, "Store") ~ "compatibility gate",
			str_detect(question_family, "Runtime|CPU") ~ "sidecar/counter observer",
			str_detect(question_family, "Product|Input mode") ~ "workload/replay claim",
			str_detect(question_family, "External display") ~ "external endpoint",
			str_detect(question_family, "CI pass/fail") ~ "policy join",
			TRUE ~ "claim-boundary guard"
		),
		action_boundary = case_when(
			str_detect(question_family, "Startup") ~ "can change reporting, not retained-q50 wait",
			str_detect(question_family, "Pattern") ~ "can change rollout wording after tail/topology policy",
			str_detect(question_family, "Selector") ~ "can change one guarded prototype after behavior/source gates",
			str_detect(question_family, "Store") ~ "blocks public data-layer action until compatibility passes",
			artifact_lane == "trigger-only" ~ "stop unless metric or wording trigger changes",
			str_detect(question_family, "CI pass/fail") ~ "blocks pass/fail prediction until policy join",
			TRUE ~ "blocks broader claim, not local benchmark fact"
		)
	)

open_question_100_pass_audit <- tibble(pass_id = 1:100) %>%
	mutate(
		question_index = ((pass_id - 1) %% nrow(open_question_100_pass_question_pool)) + 1L,
		axis_index = ((pass_id - 1) %% nrow(open_question_100_pass_axes)) + 1L
	) %>%
	left_join(
		open_question_100_pass_question_pool %>%
			mutate(question_index = row_number()),
		by = "question_index"
	) %>%
	left_join(
		open_question_100_pass_axes %>%
			mutate(axis_index = row_number()),
		by = "axis_index"
	) %>%
	mutate(
		evidence_requirement_key = paste(evidence_lane, first_field_to_check, sep = " :: "),
		question_first_seen = !duplicated(question_family),
		evidence_requirement_first_seen = !duplicated(evidence_requirement_key),
		lane_first_seen = !duplicated(evidence_lane),
		same_harness_repeat = same_harness_futility >= 4 & artifact_readiness <= 3,
		pass_disposition = case_when(
			stop_if_no_trigger >= 5 & !question_first_seen ~ "stop: trigger-only repeat",
			same_harness_repeat & !evidence_requirement_first_seen ~ "stop: same-harness repeat",
			str_detect(question_family, "Startup") ~ "metric split, not startup wait",
			str_detect(question_family, "Pattern") ~ "candidate: tail/topology gate",
			str_detect(question_family, "Selector") ~ "prototype only after source gates",
			str_detect(question_family, "Store") ~ "block until compatibility",
			str_detect(question_family, "CI pass/fail") ~ "block until policy join",
			external_reducible_score >= 5 | claim_boundary_score >= 5 ~ "claim expansion only",
			TRUE ~ "scoped wording only"
		),
		marginal_decision_value = case_when(
			pass_disposition == "candidate: tail/topology gate" & evidence_requirement_first_seen ~ 4,
			pass_disposition == "prototype only after source gates" & evidence_requirement_first_seen ~ 3,
			pass_disposition == "metric split, not startup wait" & evidence_requirement_first_seen ~ 2,
			pass_disposition %in% c("block until compatibility", "block until policy join") & evidence_requirement_first_seen ~ 2,
			evidence_requirement_first_seen & lane_first_seen ~ 1,
			TRUE ~ 0
		),
		cumulative_question_families = cumsum(question_first_seen),
		cumulative_evidence_requirements = cumsum(evidence_requirement_first_seen),
		cumulative_lanes = cumsum(lane_first_seen),
		cumulative_decision_value = cumsum(marginal_decision_value),
		pass_label = sprintf("pass %03d", pass_id)
	)

open_question_100_pass_summary <- open_question_100_pass_audit %>%
	group_by(evidence_lane, pass_disposition) %>%
	summarize(
		passes = n(),
		first_pass = min(pass_id),
		new_evidence_requirements = sum(evidence_requirement_first_seen),
		marginal_decision_value = sum(marginal_decision_value),
		max_decision_value = max(decision_value, na.rm = TRUE),
		median_same_harness_futility = median(same_harness_futility, na.rm = TRUE),
		.groups = "drop"
	) %>%
	arrange(desc(marginal_decision_value), first_pass)

open_question_100_pass_checkpoint <- open_question_100_pass_audit %>%
	filter(pass_id %in% c(1, 5, 10, 12, 20, 25, 50, 75, 100)) %>%
	select(
		pass_id,
		cumulative_question_families,
		cumulative_evidence_requirements,
		cumulative_lanes,
		cumulative_decision_value
	)

write_csv(
	open_question_100_pass_audit %>%
		select(
			pass_id,
			pressure_axis,
			question_family,
			evidence_lane,
			pass_disposition,
			challenge,
			minimum_decisive_artifact,
			first_field_to_check,
			action_boundary,
			waste_to_avoid,
			repeat_failure_mode,
			useful_artifact_class,
			question_first_seen,
			evidence_requirement_first_seen,
			lane_first_seen,
			same_harness_repeat,
			marginal_decision_value,
			cumulative_question_families,
			cumulative_evidence_requirements,
			cumulative_lanes,
			cumulative_decision_value
		),
	file.path(data_dir, "typing-delay-open-question-100-pass-saturation-audit.csv")
)

write_csv(
	open_question_100_pass_summary,
	file.path(data_dir, "typing-delay-open-question-100-pass-saturation-summary.csv")
)

write_csv(
	open_question_100_pass_checkpoint,
	file.path(data_dir, "typing-delay-open-question-100-pass-saturation-checkpoints.csv")
)

open_question_100_pass_saturation_long <- open_question_100_pass_audit %>%
	select(
		pass_id,
		`question families` = cumulative_question_families,
		`evidence requirements` = cumulative_evidence_requirements,
		`evidence lanes` = cumulative_lanes,
		`decision value` = cumulative_decision_value
	) %>%
	pivot_longer(
		cols = -pass_id,
		names_to = "saturation_metric",
		values_to = "cumulative_count"
	) %>%
	mutate(
		saturation_metric = factor(
			saturation_metric,
			levels = c("question families", "evidence requirements", "evidence lanes", "decision value")
		)
	)

save_plot(
	ggplot(open_question_100_pass_saturation_long, aes(pass_id, cumulative_count, color = saturation_metric)) +
		geom_point(alpha = 0.82, size = 1.8) +
		scale_color_brewer(type = "qual", palette = "Dark2", name = "Cumulative metric") +
		labs(
			title = "Forced 100-pass analysis saturates quickly without new artifacts",
			subtitle = "After the distinct evidence requirements are named, additional passes mostly restate blockers or claim boundaries",
			x = "Forced analysis pass",
			y = "Cumulative count / score"
		) +
		theme_minimal(base_size = 12) +
		theme(legend.position = "bottom"),
	"285-open-question-100-pass-saturation.png",
	width = 12.8,
	height = 7.2
)

save_plot(
	open_question_100_pass_summary %>%
		mutate(
			lane_label = str_wrap(evidence_lane, width = 22),
			lane_label = fct_reorder(lane_label, marginal_decision_value)
		) %>%
		ggplot(aes(marginal_decision_value, lane_label, fill = pass_disposition)) +
		geom_col(width = 0.72) +
		scale_fill_brewer(type = "qual", palette = "Set3", name = "Disposition") +
		labs(
			title = "Only target-topology and source gates keep near-term decision value",
			subtitle = "Most repeated passes are claim-boundary or external-observer work, not more local benchmark sampling",
			x = "Marginal decision value across 100 forced passes",
			y = "Evidence lane"
		) +
		theme_minimal(base_size = 12) +
		theme(legend.position = "bottom", legend.box = "vertical"),
	"286-open-question-100-pass-decision-value.png",
	width = 12.8,
	height = 8.0
)

save_plot(
	open_question_100_pass_summary %>%
		mutate(
			disposition_label = str_wrap(pass_disposition, width = 24),
			disposition_label = fct_reorder(disposition_label, passes)
		) %>%
		ggplot(aes(passes, disposition_label, fill = pass_disposition)) +
		geom_col(width = 0.72, show.legend = FALSE) +
		scale_fill_brewer(type = "qual", palette = "Paired") +
		labs(
			title = "The 100 forced passes mostly sort into stop, block, or claim-expansion buckets",
			subtitle = "A larger prompt count does not create a new local measurement requirement without a new artifact",
			x = "Forced passes",
			y = "Disposition"
		) +
		theme_minimal(base_size = 12),
	"287-open-question-100-pass-disposition-counts.png",
	width = 12.0,
	height = 7.2
)

open_question_action_frontier <- tribble(
	~question_family, ~frontier_class, ~action_scope, ~current_answer, ~minimum_new_artifact, ~pass_condition, ~fail_condition, ~current_do_not_do, ~engineering_owner, ~near_term_action_score, ~local_reducibility, ~external_dependency, ~same_harness_repeat_penalty, ~wrong_action_risk, ~evidence_readiness,
	"Startup wait and first-key tails", "target-topology gate", "CI runtime/reporting", "Retained Typing q50 does not justify adding a startup wait; first-retained and idle-return latency are separate metrics.", "Performance Tests topology artifact with failures, resources, retained rows, run order, and key-position tails.", "Reduced startup wait preserves retained q50/mean/p90, failures, resources, retained counts, and early-key tails in target topology.", "Reduced startup wait regresses failures, resources, retained counts, p90, or early-key tails.", "Do not add or remove startup waits from retained q50 alone.", "CI runtime owner", 5, 4, 3, 3, 4, 4,
	"Pattern wait replacement", "target-topology gate", "CI runtime/readiness", "The local `500ms` candidate is attractive on q50 but still has a p90/readiness rollout caveat.", "Predicate-or-fixed-wait target-topology artifact with resource quiet, preview/canvas checks, failures, retained rows, Post/Site/container lanes, and p90.", "Predicate or shorter fixed wait preserves readiness, resources, preview/canvas behavior, failures, retained q50, and p90 in the target lanes.", "Predicate fires before readiness, moves resource work into measurement, worsens p90, or diverges across target lanes.", "Do not ship a shorter pattern wait from local q50 alone.", "pattern benchmark owner", 5, 4, 3, 3, 5, 3,
	"Selector/source guard", "behavior/source gate", "source optimization", "A narrow selector guard is plausible, but behavior/source safety decides before aggregate timing.", "Behavior fixtures plus targeted before/after source-span microscope for one guarded selector owner.", "Behavior fixtures pass and the targeted source span collapses before aggregate p50 is cited.", "Behavior changes, source span does not collapse, or timing moves without the targeted owner moving.", "Do not use aggregate p50 to prove semantic safety.", "source optimization owner", 4, 5, 2, 2, 5, 4,
	"Store-subscriber partition", "compatibility gate", "data-layer/API design", "The broad fanout is real, but public store-notification partitioning is unsafe without compatibility proof.", "Public/private compatibility matrix plus migration sketch for store notification partitioning.", "Compatibility fixtures and downstream import/use cases pass under the proposed partition.", "Any public subscriber, plugin import, or ordering assumption breaks.", "Do not turn private side-channel wins into public API changes.", "data API owner", 3, 2, 4, 4, 5, 2,
	"Runtime and CPU/QoS mechanism", "new-observer gate", "mechanism wording", "The benchmark shows timing bands, but runtime/OS scheduling is below the current harness.", "Passive retained-key sidecar with CPU frequency, runnable count, thermal/QoS state, and browser event alignment.", "Sidecar counters align with the timing-band transitions without perturbing the benchmark.", "Counters disagree, observer perturbs the benchmark, or timing bands remain uncorrelated.", "Do not name a VM/runtime/OS mechanism from trace slices alone.", "mechanism owner", 2, 2, 5, 5, 3, 1,
	"Browser endpoint and display presentation", "external endpoint", "user-visible latency", "Chromium Paint/DrawFrame and RAF proxies narrow the claim, but calibrated physical presentation remains external.", "Calibrated display or high-speed-camera endpoint joined to retained key windows and trace endpoints.", "External presentation preserves the qualitative cliff or bounds the endpoint gap.", "External presentation disagrees with internal endpoints or shows a larger unseen tail.", "Do not claim physical-display latency from internal trace endpoints alone.", "presentation owner", 2, 1, 5, 5, 4, 1,
	"Product workload generalization", "workload/replay gate", "product claim", "The fixed-character large-post benchmark is not a product-wide typing workload.", "Recorded or synthetic workload replay covering human pauses, formatting, navigation, plugin-heavy posts, and IME/input modes.", "Replay strata preserve the relevant benchmark conclusions or identify narrower strata.", "Replay changes rank order, tail behavior, or the affected workload class.", "Do not generalize fixed-`x` benchmark facts to all editor lag.", "workload owner", 2, 2, 5, 5, 4, 1,
	"Input-mode realism", "topology/control gate", "benchmark method", "Held-key and complete-keypress-then-wait are distinct stimuli; the current benchmark's held-key path is not a generic tap model.", "Matched tap, short-hold, held-key, and platform-repeat controls in the target Performance Tests topology.", "The intended CI stimulus is explicitly selected and preserves the conclusion across matched controls.", "The conclusion only holds for an unintended stimulus or platform-repeat path.", "Do not mix held-key and tap conclusions without naming the stimulus.", "benchmark owner", 3, 4, 3, 3, 4, 3,
	"CI pass/fail policy", "policy join", "CI semantics", "Repository artifacts produce q50 evidence; they do not by themselves define dashboard or reviewer pass/fail policy.", "Archived CI artifact to displayed q50, dashboard threshold/noisy-metric policy, and reviewer-decision join.", "Documented policy maps raw artifact movement to the same displayed/reviewed outcome.", "Policy uses another statistic, threshold, noisy rule, or manual decision path.", "Do not predict pass/fail from local q50 alone.", "CI policy owner", 3, 1, 5, 4, 4, 1
) %>%
	mutate(
		artifact_key = str_to_lower(str_replace_all(minimum_new_artifact, "[^a-zA-Z0-9]+", "-")),
		next_artifact_value = pmax(
			0,
			near_term_action_score + wrong_action_risk + local_reducibility + evidence_readiness -
				same_harness_repeat_penalty - pmax(external_dependency - 3, 0)
		),
		repeat_more_local_samples_value = pmax(
			0,
			local_reducibility + evidence_readiness - same_harness_repeat_penalty -
				wrong_action_risk - 5
		),
		action_band = case_when(
			near_term_action_score >= 5 ~ "can move CI wait/readiness decision",
			near_term_action_score >= 4 ~ "can move source prototype",
			near_term_action_score >= 3 & external_dependency >= 4 ~ "blocked until external join",
			near_term_action_score >= 3 ~ "method/control decision",
			TRUE ~ "claim boundary only"
		),
		stop_rule = case_when(
			frontier_class == "target-topology gate" ~ "run target topology once; repeat only if failures/resources/tails disagree",
			frontier_class == "behavior/source gate" ~ "prototype one guarded source change after behavior fixtures exist",
			frontier_class == "compatibility gate" ~ "stop local timing until compatibility matrix exists",
			frontier_class == "new-observer gate" ~ "stop mechanism claims until passive sidecar exists",
			frontier_class == "external endpoint" ~ "stop display claims until calibrated endpoint exists",
			frontier_class == "workload/replay gate" ~ "stop product-wide claims until workload replay exists",
			frontier_class == "policy join" ~ "stop pass/fail claims until policy join exists",
			TRUE ~ "stop unless benchmark stimulus wording changes"
		)
	) %>%
	arrange(desc(next_artifact_value), desc(wrong_action_risk), question_family)

open_question_action_frontier_axes <- tribble(
	~pressure_axis, ~audit_question,
	"action", "Can this pass change a concrete engineering action?",
	"falsifier", "What result would overturn the current recommendation?",
	"metric", "Does q50 hide a mean, p90, first-key, failure, or resource veto?",
	"topology", "Does the target runner preserve the local result?",
	"source", "Does behavior/source safety precede timing?",
	"policy", "Is a policy or external owner needed before claiming pass/fail?",
	"claim", "Which broader claim remains blocked?",
	"cost", "Does another same-harness sample have positive marginal value?",
	"negative-control", "What negative control prevents the wrong causal story?",
	"stop-rule", "What exact condition stops the loop?"
)

open_question_action_frontier_100_pass <- tibble(pass_id = 1:100) %>%
	mutate(
		question_index = ((pass_id - 1) %% nrow(open_question_action_frontier)) + 1L,
		axis_index = ((pass_id - 1) %% nrow(open_question_action_frontier_axes)) + 1L
	) %>%
	left_join(
		open_question_action_frontier %>%
			mutate(question_index = row_number()),
		by = "question_index"
	) %>%
	left_join(
		open_question_action_frontier_axes %>%
			mutate(axis_index = row_number()),
		by = "axis_index"
	) %>%
	mutate(
		frontier_first_seen = !duplicated(question_family),
		artifact_first_seen = !duplicated(artifact_key),
		new_action_value = if_else(artifact_first_seen, next_artifact_value, 0),
		new_same_harness_value = if_else(artifact_first_seen, repeat_more_local_samples_value, 0),
		pass_result = case_when(
			!artifact_first_seen ~ "repeat: same frontier",
			frontier_class == "target-topology gate" ~ "action gate: target topology",
			frontier_class == "behavior/source gate" ~ "action gate: source prototype",
			frontier_class == "topology/control gate" ~ "method gate: stimulus controls",
			frontier_class == "compatibility gate" ~ "blocked: compatibility",
			frontier_class == "policy join" ~ "blocked: policy join",
			frontier_class %in% c("new-observer gate", "external endpoint", "workload/replay gate") ~ "blocked: claim expansion",
			TRUE ~ "scoped wording"
		),
		cumulative_frontier_questions = cumsum(frontier_first_seen),
		cumulative_artifact_bundles = cumsum(artifact_first_seen),
		cumulative_action_value = cumsum(new_action_value),
		cumulative_same_harness_value = cumsum(new_same_harness_value)
	)

open_question_action_frontier_summary <- open_question_action_frontier_100_pass %>%
	group_by(frontier_class, pass_result, action_band) %>%
