				geom_jitter(width = 0.11, height = 0, size = 2.4, alpha = 0.82, show.legend = FALSE) +
				stat_summary(fun = median, geom = "crossbar", width = 0.46, linewidth = 0.35, color = "grey20") +
				scale_color_brewer(type = "qual", palette = "Dark2", drop = FALSE) +
				labs(
